parator: Press and hold «Original» to instantly preview unmasked documents before exporting.\n- High-Performance Engine: Async thumbnail generation and granular persistence for faster loading and reduced memory usage.","release_notes_en":"What's New in MaskID 1.0.4:\n- Smart Redaction Presets: 1-tap redaction tailored for rental applications, employment onboarding, hotel check-ins, and banking, including automatic purpose watermarks.\n- QR & Barcode Detection: Automatically detect and redact 2D codes and barcodes on identity cards and official documents.\n- Hold-to-Peek Comparator: Press and hold «Original» to instantly preview unmasked documents before exporting.\n- High-Performance Engine: Async thumbnail generation and granular persistence for faster loading and reduced memory usage.","release_date":"2026-08-21","is_current":false,"source":"app_store","source_url":"https://apps.apple.com/es/app/maskid-protege-tu-identidad/id6790398619","detected_at":"2026-08-22T00:00:00.000Z","translation_status":"complete","localizations":{"es":{"locale":"es","releaseNotes":"What's New in MaskID 1.0.4:\n- Smart Redaction Presets: 1-tap redaction tailored for rental applications, employment onboarding, hotel check-ins, and banking, including automatic purpose watermarks.\n- QR & Barcode Detection: Automatically detect and redact 2D codes and barcodes on identity cards and official documents.\n- Hold-to-Peek Comparator: Press and hold «Original» to instantly preview unmasked documents before exporting.\n- High-Performance Engine: Async thumbnail generation and granular persistence for faster loading and reduced memory usage.","releaseNotesFormat":"markdown","translated":false,"provider":"app_store"},"en":{"locale":"en","releaseNotes":"What's New in MaskID 1.0.4:\n- Smart Redaction Presets: 1-tap redaction tailored for rental applications, employment onboarding, hotel check-ins, and banking, including automatic purpose watermarks.\n- QR & Barcode Detection: Automatically detect and redact 2D codes and barcodes on identity cards and official documents.\n- Hold-to-Peek Comparator: Press and hold «Original» to instantly preview unmasked documents before exporting.\n- High-Performance Engine: Async thumbnail generation and granular persistence for faster loading and reduced memory usage.","releaseNotesFormat":"markdown","translated":false,"provider":"app_store"}}},{"app_slug":"shield","version":"1.0.2","build_number":null,"release_notes":"Esta actualización incluye mejoras generales y ajustes en toda la app para una experiencia más fluida y estable.","release_notes_en":"This update includes general improvements and tweaks across the app for a smoother, more stable experience.","release_date":"2026-08-12","is_current":false,"source":"app_store","source_url":"https://apps.apple.com/es/app/maskid-protege-tu-identidad/id6790398619","detected_at":"2026-08-16T17:32:53.067Z","translation_status":"complete","localizations":{"es":{"locale":"es","releaseNotes":"Esta actualización incluye mejoras generales y ajustes en toda la app para una experiencia más fluida y estable.","releaseNotesFormat":"markdown","translated":false,"provider":"app_store"},"en":{"locale":"en","releaseNotes":"This update includes general improvements and tweaks across the app for a smoother, more stable experience.","releaseNotesFormat":"markdown","translated":true,"provider":"mymemory","translatedAt":"2026-09-06T19:11:08.172Z"}}}]$json$::jsonb;
begin
  insert into public.app_changelog (
    app_slug, version, build_number, release_notes, release_notes_en,
    release_notes_format, release_date, is_current, source, source_url,
    detected_at, translated_locales, translation_status
  )
  select p.app_slug, p.version, p.build_number, p.release_notes,
    p.release_notes_en, 'markdown', p.release_date::date, p.is_current,
    p.source, p.source_url, p.detected_at::timestamptz,
    array(select jsonb_object_keys(p.localizations)),
    p.translation_status
  from jsonb_to_recordset(payload) as p(
    app_slug text, version text, build_number text, release_notes text,
    release_notes_en text, release_date text, is_current boolean,
    source text, source_url text, detected_at text,
    translation_status text, localizations jsonb
  )
  on conflict (app_slug, version) do update set
    build_number = excluded.build_number,
    release_notes = excluded.release_notes,
    release_notes_en = excluded.release_notes_en,
    release_notes_format = excluded.release_notes_format,
    release_date = excluded.release_date,
    is_current = excluded.is_current,
    source = excluded.source,
    source_url = excluded.source_url,
    detected_at = excluded.detected_at,
    translated_locales = excluded.translated_locales,
    translation_status = excluded.translation_status;

  insert into public.app_changelog_localizations (
    changelog_id, app_slug, version, locale, release_notes,
    release_notes_format, translated, provider, translated_at
  )
  select c.id, p.app_slug, p.version, locale.key,
    locale.value->>'releaseNotes',
    coalesce(locale.value->>'releaseNotesFormat', 'markdown'),
    coalesce((locale.value->>'translated')::boolean, false),
    locale.value->>'provider',
    (locale.value->>'translatedAt')::timestamptz
  from jsonb_to_recordset(payload) as p(
    app_slug text, version text, localizations jsonb
  )
  cross join lateral jsonb_each(p.localizations) as locale(key, value)
  join public.app_changelog c on c.app_slug = p.app_slug and c.version = p.version
  where nullif(locale.value->>'releaseNotes', '') is not null
  on conflict (app_slug, version, locale) do update set
    release_notes = excluded.release_notes,
    release_notes_format = excluded.release_notes_format,
    translated = excluded.translated,
    provider = excluded.provider,
    translated_at = excluded.translated_at;
end
$seed$;
